import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    L2sq = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
    inf = L.max()
    l1 = s * s
    if inf <= 0 or l1 <= 0:
        return 0.0
    return L2sq / (l1 * inf)


def _norm(h):
    m = h.max()
    return h / m if m > 0 else h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    rng = np.random.default_rng(20240517)

    if start is not None:
        h = np.clip(np.asarray(start, dtype=float), 0.0, None)
        if h.sum() <= 0:
            h = np.ones(50)
        h = _norm(h)
    else:
        N = 300
        x = (np.arange(N) + 0.5) / N
        h = _norm(np.sin(np.pi * x) ** 2)

    N = h.size
    half = h[: (N + 1) // 2].copy()

    def full_from_half(half):
        half = np.clip(half, 0.0, None)
        if N % 2 == 0:
            return np.concatenate((half, half[::-1]))
        return np.concatenate((half, half[-2::-1]))

    best = full_from_half(half)
    bestR = _R(best)

    m = half.size
    step = 0.35

    while time.process_time() < deadline:
        improved = False
        order = rng.permutation(m)
        mx = half.max() if half.max() > 0 else 1.0
        for i in order:
            if time.process_time() > deadline:
                break
            base = half[i]
            for mult in (1 + step, 1 - step):
                cand = half.copy()
                cand[i] = base * mult if base > 0 else step * mx
                cf = full_from_half(cand)
                r = _R(cf)
                if r > bestR:
                    half = cand; best = cf; bestR = r; improved = True; base = half[i]
            for add in (step * mx, -step * mx):
                cand = half.copy()
                cand[i] = max(0.0, base + add)
                cf = full_from_half(cand)
                r = _R(cf)
                if r > bestR:
                    half = cand; best = cf; bestR = r; improved = True; base = half[i]
        if not improved:
            step *= 0.6
            if step < 1e-3:
                cand = np.clip(half * (1.0 + 0.02 * rng.standard_normal(m)), 0.0, None)
                cf = full_from_half(cand)
                r = _R(cf)
                if r > bestR:
                    half = cand; best = cf; bestR = r
                step = 0.1

    best = np.clip(best, 0.0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    return _norm(best)

import numpy as np
import time
from scipy.optimize import minimize


def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return 0.0
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    if L.size == 0:
        return 0.0
    # ||f*f||_2^2 with zero endpoints
    L0 = np.empty(L.size + 2)
    L0[0] = 0.0
    L0[1:-1] = L
    L0[-1] = 0.0
    a = L0[:-1]
    b = L0[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _cheb_basis(u, K):
    # T_0..T_K at points u
    T = np.empty((K + 1, u.size))
    T[0] = 1.0
    if K >= 1:
        T[1] = u
    for k in range(2, K + 1):
        T[k] = 2.0 * u * T[k - 1] - T[k - 2]
    return T


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    hard_deadline = t0 + budget_seconds * 0.95

    N = 512
    K = 12
    x = (np.arange(N) + 0.5) / N
    u = 2.0 * x - 1.0
    T = _cheb_basis(u, K)

    def h_from_c(c):
        logh = c[0] * T[0] + sum(c[k] * T[k] for k in range(1, K + 1))
        logh = np.clip(logh, -50.0, 50.0)
        return np.exp(logh)

    def negR(c):
        return -_R_from_h(h_from_c(c))

    rng = np.random.default_rng(12345)

    best_c = None
    best_R = -1.0

    # Seed with start if provided (fit-ish): just try a few candidates including zeros
    candidates = [np.zeros(K + 1)]
    if start is not None:
        # crude: constant log -> c0 only
        candidates.append(np.array([0.0] + [0.0] * K))

    # First evaluate candidates
    for c in candidates:
        R = _R_from_h(h_from_c(c))
        if R > best_R:
            best_R = R
            best_c = c.copy()

    # Nelder-Mead restarts with random initial c in [-1,1]
    restart = 0
    while time.process_time() < deadline:
        restart += 1
        c0 = rng.uniform(-1.0, 1.0, size=K + 1)
        # small chance to start near best
        if best_c is not None and rng.random() < 0.3:
            c0 = best_c + rng.normal(0, 0.2, size=K + 1)
        try:
            res = minimize(negR, c0, method='Nelder-Mead',
                           options={'maxiter': 2000, 'xatol': 1e-6, 'fatol': 1e-9})
            c = res.x
            R = -res.fun
        except Exception:
            continue
        if R > best_R:
            best_R = R
            best_c = c.copy()

    if best_c is None:
        best_c = np.zeros(K + 1)

    # Rebuild at N=4000
    N2 = 4000
    x2 = (np.arange(N2) + 0.5) / N2
    u2 = 2.0 * x2 - 1.0
    T2 = _cheb_basis(u2, K)

    def h_from_c2(c):
        logh = c[0] * T2[0] + sum(c[k] * T2[k] for k in range(1, K + 1))
        logh = np.clip(logh, -50.0, 50.0)
        return np.exp(logh)

    def negR2(c):
        return -_R_from_h(h_from_c2(c))

    # Short final refinement at N=1000
    N3 = 1000
    x3 = (np.arange(N3) + 0.5) / N3
    u3 = 2.0 * x3 - 1.0
    T3 = _cheb_basis(u3, K)

    def h_from_c3(c):
        logh = c[0] * T3[0] + sum(c[k] * T3[k] for k in range(1, K + 1))
        logh = np.clip(logh, -50.0, 50.0)
        return np.exp(logh)

    def negR3(c):
        return -_R_from_h(h_from_c3(c))

    if time.process_time() < hard_deadline:
        try:
            res = minimize(negR3, best_c, method='Nelder-Mead',
                           options={'maxiter': 3000, 'xatol': 1e-7, 'fatol': 1e-10})
            if -res.fun > best_R:
                best_R = -res.fun
                best_c = res.x.copy()
        except Exception:
            pass

    h_final = h_from_c2(best_c)
    # Ensure valid
    if not np.all(np.isfinite(h_final)) or h_final.sum() <= 0:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)
    return h_final

import numpy as np
import time
from scipy.optimize import minimize


def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return 0.0
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    if L.size == 0:
        return 0.0
    L0 = np.empty(L.size + 2)
    L0[0] = 0.0
    L0[1:-1] = L
    L0[-1] = 0.0
    a = L0[:-1]
    b = L0[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _resample(start, N):
    start = np.asarray(start, dtype=float).ravel()
    if start.size == N:
        return start.copy()
    if start.size == 0:
        return np.ones(N)
    x_old = np.linspace(0.0, 1.0, start.size)
    x_new = np.linspace(0.0, 1.0, N)
    h = np.interp(x_new, x_old, start)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    hard_deadline = t0 + budget_seconds * 0.95

    # Working resolution for optimization (fast convolutions)
    N = 600
    if start is not None:
        h0 = _resample(start, N)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = np.ones(N)
    else:
        h0 = np.ones(N)

    # Reparameterize via sqrt so we can do unconstrained optimization of a
    # smooth surrogate of R. Use log-height actually to keep positivity.
    eps = 1e-6
    h0 = np.maximum(h0, eps)
    v0 = np.log(h0)  # log parameterization

    def h_from_v(v):
        return np.exp(np.clip(v, -50.0, 50.0))

    def negR(v):
        return -_R_from_h(h_from_v(v))

    best_v = v0.copy()
    best_R = _R_from_h(h_from_v(best_v))

    rng = np.random.default_rng(2024)

    # Phase 1: L-BFGS-B polishing from start (good local refinement)
    if time.process_time() < deadline:
        try:
            res = minimize(negR, best_v, method='L-BFGS-B',
                           options={'maxiter': 800, 'ftol': 1e-12, 'gtol': 1e-10})
            if -res.fun > best_R:
                best_R = -res.fun
                best_v = res.x.copy()
        except Exception:
            pass
        print("after lbfgs", best_R)

    # Phase 2: random restarts / perturbations with L-BFGS-B and Nelder-Mead
    restart = 0
    while time.process_time() < deadline:
        restart += 1
        if rng.random() < 0.5:
            # perturb around the best
            scale = 0.15 if restart < 5 else 0.4
            v = best_v + rng.normal(0, scale, size=N)
        else:
            # random smooth init
            z = rng.standard_normal(N)
            k = np.array([1, 2, 3, 2, 1], dtype=float)
            k /= k.sum()
            z = np.convolve(z, k, mode='same')
            v = best_v + z * 0.5

        try:
            res = minimize(negR, v, method='L-BFGS-B',
                           options={'maxiter': 400, 'ftol': 1e-12, 'gtol': 1e-10})
            R = -res.fun
            if R > best_R:
                best_R = R
                best_v = res.x.copy()
        except Exception:
            continue

    # Phase 3: fine-grained coordinate / block search at higher resolution
    # Resample best to N2 and do a quick local Nelder-Mead on a low-dim
    # smooth basis to capture finer structure.
    N2 = 2000
    h_best = h_from_v(best_v)
    h_best = _resample(h_best, N2)
    h_best = np.maximum(h_best, 1e-9)
    v2 = np.log(h_best)

    # Use block coordinate descent: tweak small blocks with Nelder-Mead
    # on the local log-scale.
    def h_from_v2(v):
        return np.exp(np.clip(v, -50.0, 50.0))

    def negR2(v):
        return -_R_from_h(h_from_v2(v))

    best_R2 = _R_from_h(h_from_v2(v2))
    best_v2 = v2.copy()

    # Coarse-to-fine blocks: try a few passes
    block_sizes = [64, 32, 16, 8]
    pass_n = 0
    while time.process_time() < hard_deadline and pass_n < 3:
        pass_n += 1
        improved = False
        for bs in block_sizes:
            if time.process_time() >= hard_deadline:
                break
            n_blocks = max(1, N2 // bs)
            starts = np.linspace(0, N2 - bs, n_blocks).astype(int)
            for st in starts:
                if time.process_time() >= hard_deadline:
                    break
                sl = slice(st, st + bs)

                def f_local(delta):
                    v = best_v2.copy()
                    v[sl] += delta
                    return negR2(v)

                try:
                    res = minimize(f_local, np.zeros(bs), method='Nelder-Mead',
                                   options={'maxiter': 120, 'xatol': 1e-3, 'fatol': 1e-9})
                    if -res.fun > best_R2 + 1e-12:
                        best_R2 = -res.fun
                        best_v2[sl] += res.x
                        improved = True
                except Exception:
                    continue
        if not improved:
            break

    print("after blocks", best_R2)

    h_final = h_from_v2(best_v2)
    if not np.all(np.isfinite(h_final)) or h_final.sum() <= 0:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)
    return h_final
